public final class Account {
    private final String name;
    private final AccountType type;
    private final Money openingBalance;
    private Money balance;

    public Account(String name, AccountType type, Money openingBalance) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("account name is required");
        }
        if (type == null) {
            throw new IllegalArgumentException("account type is required");
        }
        if (openingBalance == null) {
            throw new IllegalArgumentException("opening balance is required");
        }
        this.name = name;
        this.type = type;
        this.openingBalance = openingBalance;
        this.balance = openingBalance;
    }

    public String name() { return name; }
    public AccountType type() { return type; }
    public Money openingBalance() { return openingBalance; }
    public Money balance() { return balance; }
}

public void applyIncome(Money amount) {
    balance = balance.add(requireAmount(amount));
}

public void applyExpense(Money amount) {
    balance = balance.subtract(requireAmount(amount));
}

public void applyTransferIn(Money amount) {
    balance = balance.add(requireAmount(amount));
}

public void applyTransferOut(Money amount) {
    balance = balance.subtract(requireAmount(amount));
}

private static Money requireAmount(Money amount) {
    if (amount == null) {
        throw new IllegalArgumentException("amount is required");
    }
    if (amount.amount().signum() <= 0) {
        throw new IllegalArgumentException("effect amount must be positive");
    }
    return amount;
}

