public interface Repository<T, ID> {
    T save(T entity);
    Optional<T> find(ID id);
    List<T> findAll();
    void delete(ID id);
}

class RepositoryContractTest {
    @Test
    void repositoryInterfaceServesBothAccountAndTransaction() {
        Repository<Account, String> accounts = new Repository<>() {
            public Account save(Account e) { return e; }
            public Optional<Account> find(String id) { return Optional.empty(); }
            public List<Account> findAll() { return List.of(); }
            public void delete(String id) { }
        };
        Repository<Transaction, String> transactions = new Repository<>() {
            public Transaction save(Transaction e) { return e; }
            public Optional<Transaction> find(String id) { return Optional.empty(); }
            public List<Transaction> findAll() { return List.of(); }
            public void delete(String id) { }
        };
        assertNotNull(accounts);
        assertNotNull(transactions);
    }
}

public class InMemoryRepository<T, ID> implements Repository<T, ID> {
    private final Map<ID, T> store = new HashMap<>();
    private final Function<T, ID> idExtractor;

    public InMemoryRepository(Function<T, ID> idExtractor) {
        this.idExtractor = idExtractor;
    }

    public T save(T entity) {
        store.put(idExtractor.apply(entity), entity);
        return entity;
    }
    public Optional<T> find(ID id) { return Optional.ofNullable(store.get(id)); }
    public List<T> findAll() { return List.copyOf(store.values()); }
    public void delete(ID id) { store.remove(id); }
}

